**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int odwroc(int n) {
    int wynik = 0;
    while (n > 0) {
        wynik = wynik * 10 + n % 10;
        n /= 10;
    }
    return wynik;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        int odw = odwroc(n);
        cout << n << ": odwrocona = " << odw;
        if (n == odw) {
            cout << " -> palindrom" << endl;
            ile++;
        } else {
            cout << endl;
        }
    }
    cout << "Palindromow: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Odwracanie liczby poprzez wielokrotne pobranie ostatniej cyfry (`n%10`) i doklejenie do wyniku (`wynik*10 + cyfra`). Palindrom <=> liczba == odwrocona.

